<script lang="ts">
	// a LabelIdentifier is an ordinary identifier, so a contextual keyword names one
	async: for (;;) break async;

	from: for (;;) break from;

	satisfies: for (;;) break satisfies;

	// the predefined-type keywords are contextual too
	string: for (;;) break string;

	any: for (;;) break any;

	undefined: for (;;) break undefined;
</script>
